import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.BF53ZjCA.js";const g=JSON.parse('{"title":"合成品与仿品鉴别","description":"","frontmatter":{"title":"合成品与仿品鉴别","identification":"synthetic-and-imitation"},"headers":[],"relativePath":"zh/identification/synthetic-and-imitation.md","filePath":"zh/identification/synthetic-and-imitation.md","lastUpdated":1790876393000}'),l={name:"zh/identification/synthetic-and-imitation.md"};function i(n,t,s,o,h,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="合成品与仿品鉴别" tabindex="-1">合成品与仿品鉴别 <a class="header-anchor" href="#合成品与仿品鉴别" aria-label="Permalink to &quot;合成品与仿品鉴别&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>判断材料时至少要分别记录四个维度：天然或人工生长、是否经过处理、是否为不同材料仿品， 以及是否存在双层石/三层石等复合结构。合成宝石、仿品、处理品和复合材料的证据路径不同， 典型线索都只能支持候选，不能替代实验室披露。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-synthetic-and-imitation-zh"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-synthetic-and-imitation-zh">边界与安全</h2><p>本页不把“天然”与“未处理”当成同义词，也不把所有非天然材料都称为“假货”。生长纹、气泡、荧光、光谱和密度等线索可能缺失、重叠或受处理影响；涉及正式披露时，应使用“支持/无法排除”表述并送专业实验室。 </p></aside><h2 id="鉴定步骤" tabindex="-1">鉴定步骤 <a class="header-anchor" href="#鉴定步骤" aria-label="Permalink to &quot;鉴定步骤&quot;">​</a></h2><p><strong>四维披露协议</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>要回答的问题</th><th>记录输出</th></tr></thead><tbody><tr><td>材料身份</td><td>它是什么材料或矿物？</td><td>候选名称、支持/冲突证据、未完成项目</td></tr><tr><td>生长来源</td><td>是天然形成还是人工生长？</td><td>生长线索、观察条件、无法确认项</td></tr><tr><td>处理状态</td><td>是否可能加热、充填、染色、辐照等？</td><td>处理线索、未核验项、披露风险</td></tr><tr><td>结构披露</td><td>是否为仿品或双层/三层/复合材料？</td><td>接合面、不同材料线索、可接触范围</td></tr></tbody></table><p>四个维度必须分开写。比如“材料是祖母绿”不等于“天然祖母绿”，“实验室培育”也不等于“未处理”；“仿品”说明材料关系，不等于对样品价值或品质的判断。</p><p><strong>证据分层矩阵</strong></p><table tabindex="0"><thead><tr><th>证据层</th><th>可以支持什么</th><th>不能独立证明什么</th><th>记录要求</th></tr></thead><tbody><tr><td>外观/照片</td><td>形成候选、发现明显结构异常</td><td>天然、合成、处理、产地</td><td>光线、背景、是否镶嵌</td></tr><tr><td>显微观察</td><td>记录包裹体、生长或接合面线索</td><td>没看见就排除某类材料</td><td>倍率、光源、方向、照片编号</td></tr><tr><td>RI/SG/光学反应</td><td>缩小材料候选范围</td><td>单独完成天然/合成披露</td><td>仪器、读数质量、重复结果</td></tr><tr><td>光谱/高级仪器</td><td>提示结构、生长或处理线索</td><td>脱离校准和实验室流程，不能独立作出最终结论</td><td>仪器、校准、光路、原始文件</td></tr><tr><td>实验室报告</td><td>形成正式身份与披露意见</td><td>把报告范围外的结论继续外推</td><td>报告编号、范围和限制</td></tr></tbody></table><p><strong>线索的正确用法</strong></p><p>曲线生长纹、气泡、铂片样包裹体、流动纹、异常色散、紫外分带和光谱模式都只能写成“可能支持线索”，并注明显微倍率、光源、方向、仪器和重复情况。没有观察到某个特征，只能说明本次条件下未观察到，不能反向证明天然或排除合成。</p><p><strong>场景矩阵：先问问题，再选证据</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>首要问题</th><th>教育性下一步</th><th>升级信号</th></tr></thead><tbody><tr><td>CVD/HPHT 钻石</td><td>材料是否为钻石，生长来源能否披露？</td><td>记录外观/显微线索，核对仪器适用性</td><td>天然/实验室培育或正式披露需求</td></tr><tr><td>合成刚玉</td><td>是否为刚玉，是否存在人工生长线索？</td><td>结合 RI、光性、显微和光谱候选</td><td>线索重叠、处理状态不明</td></tr><tr><td>水热祖母绿</td><td>材料身份与生长方式是否能分开确认？</td><td>记录包裹体、光学和设备条件</td><td>需要天然/合成或处理披露</td></tr><tr><td>玻璃 / 立方氧化锆</td><td>是否为不同材料仿品？</td><td>先记录结构和适用的物性线索</td><td>样品镶嵌、复合或结果冲突</td></tr><tr><td>双层石 / 三层石</td><td>是否存在接合面和多种材料？</td><td>只做低风险观察并标出不可见区域</td><td>任何正式结构和交易披露</td></tr></tbody></table><p><strong>推荐工作流</strong></p><ol><li>明确任务：是学习筛分、材料候选，还是正式交易/披露。</li><li>记录样品：照片、镶嵌状态、尺寸、可接触面、已有损伤和疑似复合结构。</li><li>先做低风险观察，再选择适用的物性、光学或仪器证据；不为了验证假设强行增加有损测试。</li><li>对每条线索写“支持候选 / 与候选一致 / 无法排除 / 结果不可靠”，并保留条件和原始记录。</li><li>四个披露维度分别给出结论；一个维度缺证据时写“待核验”，不补写成确定答案。</li><li>一旦出现结果冲突、样品不可接触、高价值或正式披露需求，停止继续推断并送专业实验室。</li></ol><p><strong>停止条件</strong></p><p>不把“看起来像”“没有看到异常”“某个数值接近”写成天然或合成结论。对 CVD/HPHT、合成刚玉、水热祖母绿、玻璃、立方氧化锆和复合结构，不存在一组固定测试对所有样品都充分。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>天然、处理、合成、仿品和复合材料是不同披露维度，不能压缩成一个“真/假”标签。</li><li>生长纹、气泡、铂片、流动纹、异常色散、紫外分带和光谱模式都是可能线索，不是每颗样品的必备特征。</li><li>CVD/HPHT、合成刚玉和水热祖母绿需要根据样品与设备选择交叉检测，不存在固定两项测试即可充分判断的通用规则。</li><li>典型 SG、RI 或外观差异应标注条件与来源；单值、棱角或“玻璃感”不能独立完成排除。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>钻石</td><td>立方氧化锆（CZ）</td><td>不同材料仿品候选，需结合测试与正式披露</td></tr><tr><td>祖母绿</td><td>水热合成</td><td>生长来源需要实验室核验</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA：宝石实验室分析流程</a><span>标准宝石学测试、实验室工作流与实验室培育钻石分析示例</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA：宝石产地分析方法综述</a><span>RI/SG 作为鉴定起点，以及产地判断所需的后续分析</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA：红外光谱在宝石学中的应用</a><span>光谱与原子结构、天然/合成/处理线索之间的关系</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA 宝石百科：红宝石</a><span>红宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA 宝石百科：蓝宝石</a><span>蓝宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA 宝石百科：祖母绿</a><span>祖母绿的典型 RI、双折射、比重、硬度与处理/合成/仿品边界</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA 宝石百科：尖晶石</a><span>尖晶石的典型 RI、均质性、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA 宝石百科：钻石</a><span>钻石的典型 RI、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA 宝石百科：锆石</a><span>锆石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA：堇青石（Iolite）描述</a><span>堇青石的强多色性与观察方向提示</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA：坦桑石描述</a><span>坦桑石的多色性、切磨方向、光源与热处理背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA 宝石百科：橄榄石</a><span>橄榄石典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ：沙弗莱石与翠榴石的区别</a><span>绿色石榴石颜色重叠与矿物差异提示</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',24)])])}const c=a(l,[["render",i]]);export{g as __pageData,c as default};
